SELECT m.id, m.merchant_name, m.region, m.description, m.create_time, (SELECT COUNT(*) FROM product p WHERE p.merchant_id = m.id AND p.status = 1) AS product_count FROM merchant m WHERE 1 = 1
AND m.region = #{region}
AND m.merchant_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY m.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM merchant m WHERE 1 = 1
AND m.region = #{region}
AND m.merchant_name LIKE CONCAT('%', #{keyword}, '%')
